@import "tailwindcss";

@custom-variant dark (&:where(.dark, .dark *));

@theme inline {
    --font-sans: var(--font-open-sans);
    --font-serif: var(--font-literata);
    --color-charcoal: #161616;
    --color-mist: #f6f6f6;
    --color-ink: #0f0f0f;
    --color-chalk: #f3f3f3;
    --color-evening: #a8531f;
    --color-sunset: #d6a67c;
    --color-muted: #4f4f4f;
    --color-muted-dark: #b9b9b9;
}

@layer base {
    html {
        color-scheme: light dark;
        font-size: 93.75%;
    }

    html.dark {
        color-scheme: dark;
    }

    ::selection {
        background-color: color-mix(in oklab, var(--color-evening) 85%, black);
        color: white;
    }

    html.dark ::selection {
        background-color: color-mix(in oklab, var(--color-sunset) 85%, white);
        color: var(--color-charcoal);
    }

    h1,
    h2,
    h3,
    h4,
    h5,
    h6 {
        font-family: var(--font-literata);
        font-weight: 400;
    }

    h1 {
        font-size: 2rem;
    }

    h2 {
        font-size: 1.5rem;
    }

    h3,
    h4,
    h5,
    h6 {
        font-size: 1.1875rem;
    }

    .post-content > * + * {
        margin-block-start: 1em;
    }

    .post-content p {
        color: var(--color-muted);
    }

    html.dark .post-content p {
        color: var(--color-muted-dark);
    }

    a[target="_blank"]::after {
        content: "";
        display: inline-block;
        width: 1em;
        height: 1em;
        vertical-align: -0.15em;

